rect_7 = {'top': 7, 'bottom': 12, 'left': 0, 'right': 7}
# Rectangle 2 (color 2): corners at (17,21), (17,28), (22,21), (22,28)  
rect_2 = {'top': 17, 'bottom': 22, 'left': 21, 'right': 28}

